#![forbid(unsafe_code)]
use p0_capability::ConsumedCapability; use p0_domain::{Cycle,LogicalTime,Position,State,Velocity};
pub struct Simulator { state:State, dt:f64 }
#[derive(Debug)] pub struct EffectReceipt { pub before:State, pub after:State, pub minimum_distance:f64 }
impl Simulator { pub fn new(state:State,dt:f64)->Self{Self{state,dt}} pub fn state(&self)->&State{&self.state} pub fn apply_authorized(&mut self,c:ConsumedCapability)->EffectReceipt { let before=self.state.clone(); let a=c.action.acceleration().get(); let v=before.vehicle_velocity.get(); let x=before.vehicle_position.get(); let ov=before.obstacle_velocity.get(); let ox=before.obstacle_position.get(); let nv=(v+a*self.dt).max(0.0); self.state.vehicle_position=Position::new(x+v*self.dt+0.5*a*self.dt*self.dt).unwrap(); self.state.vehicle_velocity=Velocity::new(nv).unwrap(); self.state.obstacle_position=Position::new(ox+ov*self.dt).unwrap(); self.state.time=LogicalTime(before.time.0+(self.dt*1e9) as u64); self.state.cycle=Cycle(before.cycle.0+1); let after=self.state.clone(); let minimum_distance=(after.obstacle_position.get()-after.vehicle_position.get()).min(before.obstacle_position.get()-before.vehicle_position.get()); EffectReceipt{before,after,minimum_distance} } }
